package dev.visorcompat.tacz.fabric;
public final class ModList {private static final ModList INSTANCE=new ModList();public static ModList get(){return INSTANCE;}public boolean isLoaded(String id){return net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded(id);}public java.util.Optional<Container> getModContainerById(String id){return net.fabricmc.loader.api.FabricLoader.getInstance().getModContainer(id).map(Container::new);}public record Container(net.fabricmc.loader.api.ModContainer nativeMod){public Container getModInfo(){return this;}public String getVersion(){return nativeMod.getMetadata().getVersion().getFriendlyString();}}}
